import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

@Injectable({
  providedIn: 'root'
})
export class AosService {
  private aos: any = null;
  private initialized = false;

  constructor(@Inject(PLATFORM_ID) private platformId: Object) {}

  /**
   * Ensures AOS is loaded and initialized only in the browser.
   * Uses dynamic import to avoid bundle bloat and SSR issues.
   * Deferred initialization prevents render blocking.
   */
  async ensureInitialized(): Promise<void> {
    if (!isPlatformBrowser(this.platformId) || this.initialized) {
      return;
    }

    try {
      // Check for reduced motion preference - improves UX for users with motion sensitivity
      const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      if (prefersReducedMotion) {
        // If reduced motion is preferred, do not initialize AOS or load CSS (accessibility friendly)
        this.initialized = true;
        return;
      }

      // Dynamic import - only loads in browser, reduces initial bundle size
      const aosModule = await import('aos');
      this.aos = aosModule.default;

      // Initialize AOS with performance-optimized settings
      this.aos.init({
        disable: false,
        // Use transform and opacity only - prevents layout shifts (CLS safe)
        useClassNames: true,
        // Debounce resize events for better performance
        debounceDelay: 50,
        // Throttle scroll events
        throttleDelay: 99,
        // Start animations slightly before element enters viewport for smoother UX
        offset: 120,
        // Animation duration - balanced for smooth but not jarring
        duration: 600,
        // Easing for natural feel
        easing: 'ease-out-cubic',
        // Once: true prevents re-animation on scroll up/down, reducing CPU usage
        once: true,
        // Mirror: false prevents animations on scroll up, improving performance
        mirror: false,
      });

      this.initialized = true;

      // Add js-enabled class to enable animations
      document.body.classList.add('js-enabled');

      // Load AOS CSS dynamically after JS init - non-blocking
      this.loadAosCss();

      // Schedule follow-up refreshes to account for late-loading translations, images, and fonts
      setTimeout(() => this.refresh(), 100);
      setTimeout(() => this.refresh(), 500);
      setTimeout(() => this.refresh(), 1000);
      setTimeout(() => this.refresh(), 2000);
    } catch (error) {
      console.warn('AOS initialization failed:', error);
    }
  }

  /**
   * Refreshes AOS to detect new elements with aos attributes.
   * Call this after dynamically adding elements with AOS directives.
   */
  refresh(): void {
    if (this.aos && this.initialized) {
      this.aos.refresh();

      // Run a second refresh once the browser is idle to catch late-rendered elements.
      if ('requestIdleCallback' in window) {
        requestIdleCallback(() => this.aos.refresh());
      } else {
        setTimeout(() => this.aos.refresh(), 100);
      }
    }
  }

  /**
   * Refreshes AOS on route change and resets animation state for a fresh visit.
   */
  refreshPageAnimation(): void {
    if (!this.aos || !this.initialized) {
      return;
    }

    // Check if there are any AOS elements on the page before proceeding
    const aosElements = document.querySelectorAll('[data-aos]');
    if (aosElements.length === 0) {
      // No AOS elements found, try again after a short delay
      setTimeout(() => this.refreshPageAnimation(), 100);
      return;
    }

    // First, remove existing animation classes to reset state
    this.removeAosAnimateClasses();

    // Small delay to ensure DOM is ready, then refresh
    setTimeout(() => {
      if (this.aos && this.initialized) {
        // Try refreshHard first if available (better for route changes)
        if (typeof this.aos.refreshHard === 'function') {
          this.aos.refreshHard();
        } else {
          this.aos.refresh();
        }

        // Additional refresh after a brief moment to catch any late-rendered elements
        setTimeout(() => {
          if (this.aos && this.initialized) {
            this.aos.refresh();
          }
        }, 50);
      }
    }, 50);
  }

  private removeAosAnimateClasses(): void {
    document.querySelectorAll('[data-aos].aos-animate').forEach((element) => {
      element.classList.remove('aos-animate');
    });
  }

  /**
   * Destroys AOS instance and cleans up listeners.
   * Call on app destroy if needed, but usually not necessary for SPAs.
   */
  destroy(): void {
    if (this.aos && this.initialized) {
      this.aos.destroy();
      this.initialized = false;
    }
  }

  /**
   * Dynamically loads AOS CSS after initialization.
   * Prevents render blocking by loading CSS after JS execution.
   */
  private loadAosCss(): void {
    if (!document.querySelector('link[data-aos-css]')) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = '/aos/aos.css'; // CDN for smaller bundle
      link.setAttribute('data-aos-css', 'true');
      document.head.appendChild(link);
    }
  }
}